import math

def is_power_of_two(n):
    """Checks if a positive integer n is a power of two."""
    return n > 0 and (n & (n - 1) == 0)

def get_exponent(n):
    """Returns k such that 2^k = n, assuming n is a power of two."""
    if n <= 0 or not is_power_of_two(n):
        return None
    return int(math.log2(n))

# Task parameters
N_values = [2, 3, 4]
X_values = [x for x in range(3, 21) if x % 2 != 0] # Odd x from 3 to 20

solutions = []

print("Starting systematic search...")

for n in N_values:
    for x in X_values:
        # Calculate V = x^n + x - 2
        try:
            V = x**n + x - 2
        except OverflowError:
            # Skip if the number is too large for standard integer types, though unlikely for these small bounds
            continue

        if is_power_of_two(V):
            k = get_exponent(V)
            if k is not None:
                solutions.append((x, n, k))
                print(f"Found solution: (x, n, k) = ({x}, {n}, {k}) for V = {V}")

print("\n--- Search Complete ---")
if solutions:
    print("All valid tuples found:")
    for sol in solutions:
        print(sol)
else:
    print("No solutions found in the specified range.")

